    for i in range(0, bit_length, 2):
        mask |= (1 << i)
    return n ^ mask

def frequency_Of_Smallest(n, arr):
    if n == 0:
        return 0
    smallest = min(arr)
    return arr.count(smallest)

def get_perrin(n):
    if n == 0:
        return 3
    elif n == 1:
        return 0
    elif n == 2:
        return 2
    else:
        return get_perrin(n - 2) + get_perrin(n - 3)

def swap_count(s):
    open_count = 0
    swap_count = 0
    imbalance = 0

    for char in s:
        if char == '[':
            open_count += 1
            if imbalance > 0:
                swap_count += imbalance
                imbalance -= 1
        else:
            open_count -= 1
            if open_count < 0:
                imbalance += 1
                open_count = 0

    return swap_count

def find_lucas(n):
    if n == 0:
        return 2
    elif n == 1:
        return 1
    else:
        return find_lucas(n - 1) + find_lucas(n - 2)

def get_max_sum(n):
    memo = {0: 0}

    def f(x):
        if x in memo:
            return memo[x]
        memo[x] = max(f(x // 2) + f(x // 3) + f(x // 4) + f(x // 5), x)
        return memo[x]

    return f(n)

def first_non_repeating_character(str1):
    char_count = {}
    for char in str1:
        char_count[char] = char_count.get(char, 0) + 1
    for char in str1:
        if char_count[char] == 1:
            return char
    return None

import re

def check_char(string):
    if re.match(r'^(.).*\1$', string):
        return "Valid"
    else:
        return "Invalid"

def sum_of_digits(nums):
    total = 0
    for item in nums:
        if isinstance(item, int):
            total += sum(int(digit) for digit in str(abs(item)))
    return total

def extract_freq(test_list):
    unique_tuples = {tuple(sorted(tup)) for tup in test_list}
    return len(unique_tuples)
